const b = $json.body;
const keys = (o) => o && typeof o === 'object' && !Array.isArray(o) ? Object.keys(o).sort().join(',') : '';
if (keys(b) !== 'contract,deadline,domain,operation_id,purpose,snapshot,snapshot_sha256' ||
    b.contract !== 'chief.internal-report.v1' || b.domain !== 'farming' ||
    b.purpose !== 'internal-report-preview-only' ||
    typeof b.operation_id !== 'string' || !/^[a-f0-9]{32}$/.test(b.operation_id) ||
    typeof b.snapshot_sha256 !== 'string' || !/^[a-f0-9]{64}$/.test(b.snapshot_sha256) ||
    typeof b.deadline !== 'number' || !Number.isFinite(b.deadline) ||
    b.deadline <= Date.now()/1000 || b.deadline > Date.now()/1000+30 ||
    keys(b.snapshot) !== 'as_of,counts,meaning,source_contract' ||
    b.snapshot.source_contract !== 'farm.journal-counts.v1' ||
    b.snapshot.meaning !== 'record-counts-not-production-or-stock' ||
    typeof b.snapshot.as_of !== 'string' || !b.snapshot.as_of.endsWith('Z') ||
    !Number.isFinite(Date.parse(b.snapshot.as_of)) ||
    Date.parse(b.snapshot.as_of) > Date.now()+5000 || Date.parse(b.snapshot.as_of) < Date.now()-60000 ||
    keys(b.snapshot.counts) !== 'correction_entries,current_entries,journal_entries' ||
    !Object.values(b.snapshot.counts).every(n => Number.isInteger(n) && n >= 0 && n <= 1000000000) ||
    b.snapshot.counts.current_entries > b.snapshot.counts.journal_entries ||
    b.snapshot.counts.correction_entries > b.snapshot.counts.journal_entries) {
  throw new Error('Invalid or expired record-count preview');
}
return [{json:{contract:b.contract,operation_id:b.operation_id,domain:b.domain,
  snapshot:b.snapshot,snapshot_sha256:b.snapshot_sha256,status:'COMPLETED'}}];
